-- Proposal only. No deployment. Production RLS and approvals require hardening.
create extension if not exists pgcrypto;
create table if not exists public.dealerships(id uuid primary key default gen_random_uuid(),name text not null unique,created_at timestamptz not null default now());
create table if not exists public.memberships(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),dealership_id uuid not null references public.dealerships(id),role text not null check(role in('super_admin','dealership_manager','crm_executive','service_team','management')),unique(user_id,dealership_id));
create table if not exists public.ai_agents(id uuid primary key default gen_random_uuid(),name text not null,dealership_id uuid references public.dealerships(id),is_shared boolean not null default false,provider text not null default 'sarvam',provider_agent_id text,approved_version text,created_at timestamptz default now());
create table if not exists public.customers(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references public.dealerships(id),name text not null,mobile text,consent_status text not null default 'unverified',do_not_call boolean not null default false,created_at timestamptz default now());
create table if not exists public.vehicles(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references public.dealerships(id),model text,registration_number text,created_at timestamptz default now());
create table if not exists public.customer_vehicles(customer_id uuid references public.customers(id),vehicle_id uuid references public.vehicles(id),primary key(customer_id,vehicle_id));
create table if not exists public.uploads(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references public.dealerships(id),uploaded_by uuid references auth.users(id),filename text not null,status text not null default 'pending',created_at timestamptz default now());
create table if not exists public.campaigns(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references public.dealerships(id),name text not null,agent_id uuid references public.ai_agents(id),agent_version text,status text not null default 'DRAFT',scheduled_for timestamptz,cohort_hash text,approved_hash text,sarvam_campaign_id text unique,created_by uuid references auth.users(id),created_at timestamptz default now());
create table if not exists public.campaign_contacts(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.campaigns(id),customer_id uuid references public.customers(id),vehicle_id uuid references public.vehicles(id),snapshot jsonb not null default '{}'::jsonb);
create table if not exists public.approvals(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references public.campaigns(id),manager_id uuid not null references auth.users(id),decision text not null check(decision in('APPROVED','REJECTED')),snapshot_hash text not null,reason text,created_at timestamptz not null default now());
create table if not exists public.call_attempts(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references public.dealerships(id),campaign_id uuid references public.campaigns(id),sarvam_call_id text unique,status text,call_started_at timestamptz,call_ended_at timestamptz,summary text,transcript text,output_variables jsonb not null default '{}'::jsonb,created_at timestamptz default now());
create table if not exists public.tasks(id uuid primary key default gen_random_uuid(),dealership_id uuid not null references public.dealerships(id),call_id uuid references public.call_attempts(id),type text not null check(type in('callback','appointment','pickup_drop','complaint','other')),status text not null default 'REQUESTED',assigned_to uuid references auth.users(id),detail jsonb not null default '{}'::jsonb,created_at timestamptz default now());
create table if not exists public.integration_events(id uuid primary key default gen_random_uuid(),provider text not null,external_event_id text not null unique,payload jsonb not null,processed_at timestamptz,created_at timestamptz default now());
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id),dealership_id uuid references public.dealerships(id),action text not null,object_id uuid,details jsonb default '{}'::jsonb,created_at timestamptz default now());
-- Default-deny all exposed tables until reviewed production policies and server-side flows are installed.
do $$declare r record;begin for r in select tablename from pg_tables where schemaname='public' and tablename in ('dealerships','memberships','ai_agents','customers','vehicles','customer_vehicles','uploads','campaigns','campaign_contacts','approvals','call_attempts','tasks','integration_events','audit_logs') loop execute format('alter table public.%I enable row level security',r.tablename);end loop;end$$;
-- Intentionally no permissive RLS policies; all client reads and writes fail closed.
